class Handler4HttpDelay2 extends SimpleChannelHandler
{
       private long start = 0;

   public Handler4HttpDelay2()
   {}

   public void channelConnected(ChannelHandlerContext ctx,
ChannelStateEvent e) throws Exception
   {
       start = System.currentTimeMillis();
   }

   public void messageReceived(ChannelHandlerContext ctx, final
MessageEvent e) throws Exception
   {
       System.out.println(Thread.currentThread());
               long now = System.currentTimeMillis();
               int milseconds = (int)(now - start);
       try
       {
               e.getChannel().close();
       }
       catch(Exception e2)
       {}
       System.out.println("Delay is " + milseconds);
   }

   public void exceptionCaught(ChannelHandlerContext ctx,
ExceptionEvent e) throws Exception
   {
       e.getCause().printStackTrace();
       try
       {
               e.getChannel().close();
       }
       catch(Exception e2)
